import{_ as r,y as a,a as i,o,a2 as e,D as s}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"configure/notifications.md","filePath":"configure/notifications.md","lastUpdated":1789441803000}'),d={name:"configure/notifications.md"};function c(h,t,m,l,f,g){const n=a("ImagePopup");return o(),i("div",null,[t[0]||(t[0]=e('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>The <strong>Notifications</strong> screen decides which emails your store sends to customers, to the admin and to inventory sources. Each switch applies to the whole store.</p><ol><li>Go to <strong>Configure &gt;&gt; Email &gt;&gt; Notifications</strong>.</li><li>In <strong>Notifications</strong>, switch each email on or off, as described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),s(n,{src:"/images/configure/email-notifications.png",alt:"Notifications screen with a switch for each email"}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Send a confirmation e-mail after customer registration</strong></td><td>Sends the customer a welcome email when their account is created, on the storefront or in the admin panel. A customer who signs up on the storefront while email verification is on gets it after verifying their address.</td></tr><tr><td><strong>Send a confirmation e-mail to admin after customer registration</strong></td><td>Sends the admin an email when a customer account is created, on the storefront or in the admin panel.</td></tr><tr><td><strong>Send the customer account credentials after registration</strong></td><td>Sends the customer their sign-in details when you create their account in the admin panel.</td></tr><tr><td><strong>Send a confirmation e-mail to the customer after placing a new order</strong></td><td>Sends the customer an order confirmation after they place an order.</td></tr><tr><td><strong>Send a confirmation e-mail to the admin after placing a new order</strong></td><td>Sends the admin an email when an order is placed.</td></tr><tr><td><strong>Send a notification e-mail to the customer after creating a new invoice</strong></td><td>Sends the customer an email when an invoice is created for their order.</td></tr><tr><td><strong>Send a notification e-mail to the admin after creating a new invoice</strong></td><td>Sends the admin an email when an invoice is created.</td></tr><tr><td><strong>Send a notification e-mail to the customer after creating a refund</strong></td><td>Sends the customer an email when a refund is created for their order.</td></tr><tr><td><strong>Send a notification e-mail to the admin after creating a new refund</strong></td><td>Sends the admin an email when a refund is created.</td></tr><tr><td><strong>Send a notification e-mail to the customer after creating a shipment</strong></td><td>Sends the customer an email when a shipment is created for their order.</td></tr><tr><td><strong>Send a notification e-mail to the admin after creating a new shipment</strong></td><td>Sends the admin an email when a shipment is created.</td></tr><tr><td><strong>Send a notification e-mail to the inventory source after creating a shipment</strong></td><td>Sends the contact of the inventory source the shipment is sent from an email when the shipment is created.</td></tr><tr><td><strong>Send a notification to customer after canceling an order</strong></td><td>Sends the customer an email when their order is canceled.</td></tr><tr><td><strong>Send a notification e-mail to admin after canceling an order</strong></td><td>Sends the admin an email when an order is canceled.</td></tr></tbody></table><p>A new installation switches on every email to customers, the email to the inventory source and the new order email to the admin, and leaves the other emails to the admin off.</p><p>Emails are sent from the addresses set under <a href="./email-settings.html">Email Settings</a>, and emails to the admin go to the <strong>Admin Email Address</strong> set there.</p><p>The actions that send these emails are described in <a href="./../customer/create-customer.html">Customers</a>, <a href="./../orders/create-order.html">Create Order</a>, <a href="./../orders/orders.html#emails">Orders</a>, <a href="./../orders/create-invoice.html">Create Invoice</a>, <a href="./../orders/create-shipment.html">Create Shipment</a>, <a href="./../orders/create-refunds.html">Create Refund</a> and <a href="./../orders/rma.html#emails">Return Merchandise Authorization (RMA)</a>.</p>',4))])}const S=r(d,[["render",c]]);export{p as __pageData,S as default};
